namespace minishield {

llvm::PreservedAnalyses StatsPass::run(
    llvm::Function &F,
    llvm::FunctionAnalysisManager &AM) {

    if (F.isDeclaration())
        return llvm::PreservedAnalyses::all();

    int cond_br = 0, uncond_br = 0, calls = 0, total_inst = 0,
        switches = 0, phis = 0, returns = 0, invokes = 0,
        indirectBranches = 0;

    for (const llvm::BasicBlock &BB : F) {
        for (const llvm::Instruction &I : BB) {
            ++total_inst;
            switch (I.getOpcode()) {
                case llvm::Instruction::CondBr:
                    ++cond_br;
                    break;
                case llvm::Instruction::UncondBr:
                    ++uncond_br;
                    break;
                case llvm::Instruction::Switch:
                    ++switches;
                    break;
                case llvm::Instruction::PHI:
                    ++phis;
                    break;
                case llvm::Instruction::Ret:
                    ++returns;
                    break;
                case llvm::Instruction::Call:
                    ++calls;
                    break;
                case llvm::Instruction::Invoke:
                    ++invokes;
                    break;
                case llvm::Instruction::IndirectBr:
                    ++indirectBranches;
                    break;
                default:
                    break;
            }
        }
    }

    llvm::errs() << "[MiniShield] function: " << F.getName()
        << ", blocks: " << F.size()
        << ", total instructions: " << total_inst
        << ", phi: " << phis
        << ", returns: " << returns
        << ", switches: " << switches
        << ", calls: " << calls
        << ", invokes: " << invokes
        << ", indirect branches: " << indirectBranches
        << ", conditional branches: " << cond_br
        << ", unconditional branches: " << uncond_br << "\n";

    return llvm::PreservedAnalyses::all();
}
